structure.mermaidSource:
flowchart TD
  start["Início: Analisar ocorrência da palavra 'SE'"] --> dec_caminho{"Atua como Conjunção ou Pronome?"}
  dec_caminho -- "Pronome" --> res_bloco_pronome["Encaminhar para Bloco dos Pronomes (PA, PIS, PIV, Reflexivo)"]
  dec_caminho -- "Conjunção" --> dec_tipo_conj{"Conecta oração Substantiva ou Adverbial?"}
  dec_tipo_conj -- "Substantiva" --> proc_teste_integrante["Testar substituição por ISSO / DISSO / NISSO"]
  proc_teste_integrante --> dec_valida_isso{"Aceita 'ISSO / DISSO / NISSO'?"}
  dec_valida_isso -- "Sim" --> res_conj_integrante["Classificação: Conjunção Integrante"]
  dec_valida_isso -- "Não" --> dec_tipo_conj
  dec_tipo_conj -- "Adverbial" --> dec_circunstancia{"Qual a circunstância expressa com a principal?"}
  dec_circunstancia -- "Condição" --> res_adv_condicional["Conjunção Adverbial Condicional (troca por 'caso')"]
  dec_circunstancia -- "Concessão" --> res_adv_concessiva["Conjunção Adverbial Concessiva (troca por 'embora')"]
  dec_circunstancia -- "Causa" --> res_adv_causal["Conjunção Adverbial Causal (troca por 'já que')"]

flowchart TD
  start["Início: Análise da partícula 'se'"] --> dec_comutacao{"Admite substituição por 'caso' (ou 'desde que')?"}
  dec_comutacao -- "Não" --> res_nao_cond["Resultado: Não é conjunção condicional"]
  dec_comutacao -- "Sim" --> dec_hipotese{"A oração expressa hipótese ou condição?"}
  dec_hipotese -- "Não" --> res_nao_cond
  dec_hipotese -- "Sim" --> dec_modo{"O verbo da oração está no modo subjuntivo?"}
  dec_modo -- "Não" --> res_nao_cond
  dec_modo -- "Sim" --> res_cond["Resultado: Conjunção Subordinativa Condicional"]

flowchart TD
  start["Início: Análise da partícula 'se'"] --> dec_contraste{"Há duas ideias em contraste ou oposição?"}
  dec_contraste -- "Não" --> res_nao_conc["Resultado: Não é conjunção concessiva"]
  dec_contraste -- "Sim" --> dec_embora{"Admite troca por 'embora' ou 'mesmo que'?"}
  dec_embora -- "Não" --> res_nao_conc
  dec_embora -- "Sim" --> dec_sentido{"A oposição/ressalva semântica se mantém idêntica?"}
  dec_sentido -- "Não" --> res_nao_conc
  dec_sentido -- "Sim" --> res_conc["Resultado: Conjunção Subordinativa Concessiva"]

flowchart TD
  start["Início: Análise da partícula 'se'"] --> dec_causal_comut{"Admite troca por 'já que', 'visto que' ou 'uma vez que'?"}
  dec_causal_comut -- "Não" --> res_nao_causal["Resultado: Não é conjunção causal"]
  dec_causal_comut -- "Sim" --> dec_fato{"O conteúdo é apresentado como fato real (não hipótese)?"}
  dec_fato -- "Não" --> res_prov_cond["Resultado: Hipótese identificada (provável Condicional)"]
  dec_fato -- "Sim" --> dec_indicativo{"O verbo da oração está no modo Indicativo?"}
  dec_indicativo -- "Não" --> res_nao_causal
  dec_indicativo -- "Sim" --> dec_estrutura{"A oração expressa a causa/motivo do evento principal?"}
  dec_estrutura -- "Não" --> res_nao_causal
  dec_estrutura -- "Sim" --> res_causal["Resultado: Conjunção Subordinativa Causal"]

flowchart TD
  start["Início: Análise da Oração Subordinada com 'SE'"] --> dec_valor_logico{"Passo 1: Qual o valor lógico da oração com 'SE'?"}
  dec_valor_logico -- "Hipótese / Incerteza" --> dec_modo_hipotese{"Passo 2A: Verbo no Modo Subjuntivo?"}
  dec_valor_logico -- "Fato / Realidade" --> dec_modo_fato{"Passo 2B: Verbo no Modo Indicativo?"}
  dec_modo_hipotese -- "Sim" --> dec_subst_condicional{"Passo 3A: Aceita 'Caso' ou 'Desde que'?"}
  dec_modo_hipotese -- "Não" --> res_analise_contextual["Reavaliação: Hipótese com Indicativo"]
  dec_subst_condicional -- "Sim" --> res_condicional["Oração Subordinada Adverbial Condicional"]
  dec_subst_condicional -- "Não" --> res_analise_contextual
  dec_modo_fato -- "Sim" --> dec_subst_causal{"Passo 3B: Aceita 'Já que' ou 'Visto que'?"}
  dec_modo_fato -- "Não" --> res_analise_contextual
  dec_subst_causal -- "Sim" --> res_causal["Oração Subordinada Adverbial Causal"]
  dec_subst_causal -- "Não" --> res_outras_funcoes["Outra Função do 'SE' (Ex.: Integrante)"]

items.analysis:
Tipo: Exemplo de conjunção condicional.
Classificação: Conjunção condicional.
Justificativas:
- Admite substituição pela conjunção “caso” (“Caso todos concordem, podemos partir”);
- Expressa uma situação hipotética/condição;
- O verbo “concordarem” está flexionado no futuro do subjuntivo.

